import * as React from "react";

export type MetronomeTickIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MetronomeTickIcon({ size = 20, ...props }: MetronomeTickIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M9 3.5h6L18 20H6Z" /><circle cx="12" cy="12" r="1.5" />
    </svg>
  );
}
